changeSet.sql:
DO
$$
BEGIN
    IF
NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'dewtally_app') THEN
CREATE ROLE dewtally_app NOLOGIN;
END IF;
END
$$;

rollback.sql:
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE SELECT, INSERT, UPDATE, DELETE ON TABLES FROM
dewtally_app;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM dewtally_app;
REVOKE USAGE ON SCHEMA public FROM dewtally_app;
DROP ROLE dewtally_app;

changeSet.sql:
ALTER TABLE invoice_document ENABLE ROW LEVEL SECURITY;
CREATE
POLICY tenant_isolation ON invoice_document
    USING (tenant_id = current_tenant_id());

ALTER TABLE invoice ENABLE ROW LEVEL SECURITY;
CREATE
POLICY tenant_isolation ON invoice
    USING (tenant_id = current_tenant_id());

ALTER TABLE invoice_change ENABLE ROW LEVEL SECURITY;
CREATE
POLICY tenant_isolation ON invoice_change
    USING (tenant_id = current_tenant_id());

ALTER TABLE supplier ENABLE ROW LEVEL SECURITY;
CREATE
POLICY tenant_isolation ON supplier
    USING (tenant_id = current_tenant_id());

-- Child tables without tenant_id: visible only if the parent row is visible
-- (the subquery itself is filtered by the parent's policy).
ALTER TABLE invoice_line ENABLE ROW LEVEL SECURITY;
CREATE
POLICY tenant_isolation ON invoice_line
    USING (EXISTS (SELECT 1 FROM invoice i WHERE i.id = invoice_line.invoice_id));

ALTER TABLE validation_issue ENABLE ROW LEVEL SECURITY;
CREATE
POLICY tenant_isolation ON validation_issue
    USING (EXISTS (SELECT 1 FROM invoice i WHERE i.id = validation_issue.invoice_id));

ALTER TABLE supplier_iban ENABLE ROW LEVEL SECURITY;
CREATE
POLICY tenant_isolation ON supplier_iban
    USING (EXISTS (SELECT 1 FROM supplier s WHERE s.id = supplier_iban.supplier_id));

rollback.sql:
DROP POLICY tenant_isolation ON supplier_iban;
ALTER TABLE supplier_iban DISABLE ROW LEVEL SECURITY;
DROP POLICY tenant_isolation ON validation_issue;
ALTER TABLE validation_issue DISABLE ROW LEVEL SECURITY;
DROP POLICY tenant_isolation ON invoice_line;
ALTER TABLE invoice_line DISABLE ROW LEVEL SECURITY;
DROP POLICY tenant_isolation ON supplier;
ALTER TABLE supplier DISABLE ROW LEVEL SECURITY;
DROP POLICY tenant_isolation ON invoice_change;
ALTER TABLE invoice_change DISABLE ROW LEVEL SECURITY;
DROP POLICY tenant_isolation ON invoice;
ALTER TABLE invoice DISABLE ROW LEVEL SECURITY;
DROP POLICY tenant_isolation ON invoice_document;
ALTER TABLE invoice_document DISABLE ROW LEVEL SECURITY;
DROP FUNCTION current_tenant_id();
